module tb;

  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  logic        clk = 1'b0;
  logic        rst = 1'b0;
  always #4 clk = ~clk;   // 125 MHz clock

  // ------------------------------------------------------------
  // DUT internal signals
  // ------------------------------------------------------------
  logic        rxd_drive;          // driven start/stop bits
  logic [7:0]  s_axis_tdata = 0;
  logic        s_axis_tvalid = 0;
  logic        s_axis_tready = 1'b1;

  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready = 1'b1;

  logic        txd;                // unused output
  logic        tx_busy;
  logic        rx_busy;
  logic        rx_overrun_error;
  logic        rx_frame_error;
  logic [15:0] prescale_val = 16'd5; // fixed prescale

  // ------------------------------------------------------------
  // Instantiate the DUT (uart) with default parameters
  // ------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (s_axis_tready),
    .m_axis_tdata      (m_axis_tdata),
    .m_axis_tvalid     (m_axis_tvalid),
    .m_axis_tready     (m_axis_tready),
    .rxd               (rx_drive),
    .txd               (txd),
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale_val)
  );

  // ------------------------------------------------------------
  // Helper timing parameters
  // ------------------------------------------------------------
  localparam int BIT_CLOCKS = 5 * 8; // 40 system clocks per UART bit

  // ------------------------------------------------------------
  // Task: drive a UART frame (start + 8 data + stop)
  // ------------------------------------------------------------
  task automatic drive_frame (input byte unsigned data_byte);
    integer i;
    begin
      // start bit (low)
      rxd_drive = 1'b0;
      repeat (BIT_CLOCKS) @(posedge clk);

      // data bits, LSB first
      for (i = 0; i < 8; i = i + 1) begin
        rxd_drive = data_byte[i];
        repeat (BIT_CLOCKS) @(posedge clk);
      end

      // stop bit (high)
      rxd_drive = 1'b1;
      repeat (BIT_CLOCKS) @(posedge clk);
    end
  endtask

  // ------------------------------------------------------------
  // Detect first received word (m_axis_tvalid rises)
  // ------------------------------------------------------------
  logic first_word_seen = 1'b0;
  always @(posedge clk) begin
    if (!first_word_seen && $rose(m_axis_tvalid)) begin
      first_word_seen <= 1'b1;
      $display("[%0t] first_word_seen", $time);
    end
  end

  // ------------------------------------------------------------
  // After first word, wait 2 clocks then start second frame (0x5A)
  // ------------------------------------------------------------
  // Wait exactly 2 system clocks after the rise
  always @(posedge clk) begin
    if (first_word_seen) begin
      #0; // schedule after current edge
      repeat (2) @(posedge clk);
      drive_frame(8'h5A); // second frame delivers 0x5A
      // Now wait for the second word to be delivered with correct data
      wait_for_target();
      $finish;
    end
  end

  // ------------------------------------------------------------
  // Wait for the second valid word (data == 0x5A, frame_error == 0)
  // ------------------------------------------------------------
  task automatic wait_for_target();
    begin
      // Poll for a valid word with the expected payload and no frame error
      repeat (2000) begin
        @(posedge clk);
        if (m_axis_tvalid && !rx_frame_error && m_axis_tdata == 8'h5A) begin
          $display("[%0t] target coverage point observed", $time);
          $finish;
        end
      end
      $fatal(1, "Target coverage point not observed before timeout");
    end
  endtask

  // ------------------------------------------------------------
  // Reset sequence
  // ------------------------------------------------------------
  initial begin
    // 1) Apply reset
    rst = 1'b1;
    repeat (2) @(negedge clk);
    rst = 1'b0;
    repeat (2) @(negedge clk);

    // 2) Idle a couple of cycles before first frame
    repeat (4) @(negedge clk);

    // 3) Drive first arbitrary frame (e.g., 0xA5)
    drive_frame(8'hA5);

    // The rest of the flow is handled by the always block above.
  end

  // ------------------------------------------------------------
  // Connect DUT ports that are not explicitly driven
  // ------------------------------------------------------------
  // The AXI‑Stream side is kept idle (s_axis_tvalid always low)
  // All unused output ports are simply left unconnected.

endmodule

